mapper.insert:
INSERT INTO ${tableName} (id, lock_name)
SELECT #{id}, #{lockName}
WHERE NOT EXISTS (SELECT 1 FROM ${tableName} WHERE lock_name = #{lockName})

mapper.update:
UPDATE ${tableName} SET locked_by = #{ownerId}, locked_until = #{until}
WHERE lock_name = #{lockName}
  AND (locked_by IS NULL OR locked_by = #{ownerId}
       OR locked_until IS NULL OR locked_until < #{now})
